import{_ as t,o,c as i,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const p=JSON.parse('{"title":"Invoices Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Invoices Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/invoices-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Invoices Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/invoices-overview"}]]},"headers":[],"relativePath":"user-guide/invoices-overview.md","filePath":"user-guide/invoices-overview.md","lastUpdated":1787517118000}'),n={name:"user-guide/invoices-overview.md"};function d(r,e,s,c,l,u){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="invoices-module" tabindex="-1">Invoices Module <a class="header-anchor" href="#invoices-module" aria-label="Permalink to &quot;Invoices Module&quot;">​</a></h1><p>Tenant customer-billing module on the frozen platform — the first Phase 3 (Billing) module. Mirrors the <a href="/user-guide/quotations-overview">Quotations</a> / <a href="/user-guide/contracts-overview">Contracts</a> notes/timeline/assignment pattern, extended with a status-driven balance (<code>amount_paid</code>, <code>amount_credited</code>, <code>balance_due</code>) that the <a href="/user-guide/payments-overview">Payments</a> and <a href="/user-guide/credit-notes-overview">Credit Notes</a> modules now drive.</p><p><strong>No hard dependency.</strong> Unlike Quotations/Contracts (which require Opportunities), Invoices has <strong>no required <code>module_dependencies</code> row</strong> — it can be installed on its own. Contact, Company, and Quotation links are all optional and only validated when their module is entitled.</p><blockquote><p><strong>Naming note:</strong> the backend model is <code>CustomerInvoice</code> (table <code>customer_invoices</code>) — distinct from the platform&#39;s own Central billing <code>Invoice</code> model (subscription invoices the platform sends <em>to</em> tenants). This module lets a tenant bill <em>its own</em> customers.</p></blockquote><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/invoices">invoices.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/invoices">invoices.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/invoices">invoices.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/quotations-overview">quotations.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-invoices">../api/tenant-v1-invoices.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Invoice fields: title, optional contact/company link, optional quotation / estimate / contract links, currency, issue date, due date, notes</li><li>Recurring series (weekly / monthly / quarterly / semi-annually / yearly). <strong>Next invoice date</strong> auto-fills from the issue date plus frequency and can be overridden; later drafts follow the frequency from that date. <strong>Stop recurring</strong> ends the series without voiding history</li><li>Download invoice PDF (workspace-branded from Settings → Branding: color, logo, company profile, bank details)</li><li><strong>Email customer</strong> after Send (<code>POST /invoices/{id}/email</code>, <code>invoices.send</code>) — optional PDF attachment; default recipient from linked contact/company; records <code>emailed</code> timeline + tenant email log</li><li>Auto-numbered (<code>INV-00001</code>; prefix backed by the <code>invoices_number_prefix</code> tenant setting, default <code>INV-</code> — editable under <strong>Settings → General → Document number prefixes</strong>)</li><li>Line items (description, quantity, unit price, tax rate) — subtotal / tax total / total computed server-side</li><li>Balance tracking: <code>amount_paid</code>, <code>amount_credited</code>, <code>balance_due</code> (read-only via this API — <code>amount_paid</code>/<code>balance_due</code> are populated by <a href="/user-guide/payments-overview">Payments</a>; <code>amount_credited</code>/<code>balance_due</code> are populated by <a href="/user-guide/credit-notes-overview">Credit Notes</a>)</li><li>Status workflow: <code>draft → unpaid → paid | cancelled</code> (<code>POST /invoices/{id}/send</code>, <code>.../void</code> cancels, <code>.../status</code>) — <code>paid</code> is set automatically as Payments clear the balance; partial payments stay <code>unpaid</code></li><li>Assignment with assignee scoping via <code>invoices.assign</code></li><li>Notes + domain activity timeline (mirrors Quotations)</li><li>Trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong></li><li>Module licensing (<code>module:invoices</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong> (Billing category)</li><li>Audit + activity logging; assignment notification</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>invoices.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code> · <code>send</code> · <code>void</code></p><p>Enable Invoices from Marketplace (free) — no other module is required first. Catalog: slug <code>invoices</code>, category <code>billing</code>, <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 10</code>, version <strong>1.8.0</strong>.</p><h2 id="related-modules" tabindex="-1">Related modules <a class="header-anchor" href="#related-modules" aria-label="Permalink to &quot;Related modules&quot;">​</a></h2><p><strong>No hard dependency.</strong> <strong>Optional:</strong> Contacts and Companies (customer pickers only appear/validate when entitled), Quotations (an invoice may optionally reference the quotation it was generated from), <a href="/user-guide/accounting-overview">Accounting</a> (soft: <strong>Send</strong> posts Dr AR / Cr Revenue). <a href="/user-guide/payments-overview">Payments</a> and <a href="/user-guide/credit-notes-overview">Credit Notes</a> both hard-depend on Invoices (not the other way around). See <a href="/architecture/module-dependencies">Module Dependencies</a>.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Multi-currency conversion</li></ul>',15)])])}const h=t(n,[["render",d]]);export{p as __pageData,h as default};
